import{_ as e,o as l,c as t,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Orchestrator Meeting 2022-06-14","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2022-06-14","date":"2022-06-14T00:00:00.000Z","updated":"2022-06-29T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH algorithm","高可用性","可扩展性","对象存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-06-14.md","filePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-06-14.md","lastUpdated":1780460162000}'),r={name:"posts/2022/Ceph_Orchestrator_Meeting_2022-06-14.md"};function o(n,a,s,h,u,c){return l(),t("div",null,[...a[0]||(a[0]=[i('<h3 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h3><p>在2022年6月14日的Ceph Orchestrator会议中，讨论了以下主要议题：</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>Paul的磁盘重扫描功能</strong></p><ul><li>讨论了Paul提出的磁盘重扫描功能，该功能可能作为现有staff volume inventory的替代方案。目前有一个相关的Pull Request（PR）已开放，但尚未被审查。会议建议团队成员提供直接反馈，并计划下周继续讨论该议题。</li></ul></li><li><p><strong>HNFS for OpenStack的概念验证</strong></p><ul><li>Ramana提供了关于HNFS for OpenStack的概念验证进展更新。Francisco主要负责，已成功手动复制和编辑了现有的NFS Ganesha服务的脚本，并进行了一些代码修改。Ramana请求Francisco分享详细步骤的Google文档，并计划将其链接到跟踪票证。</li></ul></li><li><p><strong>FADM重构工作</strong></p><ul><li>John将开始关注FADM的重构工作。他计划首先本地拉取分支，运行现有代码，以了解PR实施的工作流程。John提到他正在处理GoTheft的发布周期，因此今天没有时间处理此事。</li></ul></li><li><p><strong>平衡静态放置支持</strong></p><ul><li>讨论了关于平衡静态放置支持的请求，该请求由Ernesto提出。目前使用的是基于计数的放置策略，导致所有守护进程都放置在同一主机上，形成热点。会议认为这不是紧急问题，但未来可能需要考虑解决方案。</li></ul></li><li><p><strong>安全功能更新</strong></p><ul><li>讨论了某些守护进程中TLS和SSL功能标记为实验性的问题。开发者表示这些功能已可操作，但未来可能会有变动。会议建议在默认情况下关闭这些功能，并在版本更新时保持谨慎。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>团队成员应审查并提供关于Paul磁盘重扫描功能PR的反馈。</li><li>Francisco将分享HNFS for OpenStack概念验证的详细步骤文档，并链接到跟踪票证。</li><li>John将开始FADM重构工作，并计划在本地运行现有代码以了解工作流程。</li><li>平衡静态放置支持的问题被标记为未来需要考虑的事项。</li><li>对于实验性的TLS和SSL功能，建议在默认情况下关闭，并在版本更新时保持谨慎。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>下周会议将讨论Paul的磁盘重扫描功能PR的反馈和进展。</li><li>下周会议将讨论HNFS for OpenStack概念验证的详细步骤文档。</li><li>John将继续FADM重构工作，并计划在下周提供更新。</li><li>对于平衡静态放置支持的问题，将收集更多信息并评估具体需求。</li><li>对于实验性的TLS和SSL功能，将保持关注并在版本更新时进行相应调整。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>会议提醒团队成员注意安全功能的实验性状态，并在实施时保持谨慎。</li><li>下周会议将讨论RDW和多站点相关事宜。</li></ul><h3 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h3><ul><li>会议在确认无其他议题后结束，并计划下周继续讨论相关事宜。</li></ul>',12)])])}const _=e(r,[["render",o]]);export{d as __pageData,_ as default};
